  +/* ─────────────────────────────────────────────────────────────
  + * Dossier folio — the viewport-locked filing surface
  + *
  + * The dossier is one sheet in a machine, not a scrolling web page:
  + * the folio fills the viewport, the two columns scroll inside their
  + * own frames, and advancing a step feeds a new sheet through the
  + * platen rather than repainting the page.
  + *
  + *   .folio-shift     : the sheet-feed on every step change
  + *   .folio-rail      : the department index along the bottom
  + *   .carriage-input  : platen underline that travels on focus
  + *   .type-caret      : blinking block caret on the live field
  + *   .field-live      : the preview card currently being typed into
  + * ───────────────────────────────────────────────────────────── */
  +
  +@keyframes folio-feed {
  +  from {
  +    opacity: 0;
  +    transform: translateY(0.6rem);
  +  }
  +  to {
  +    opacity: 1;
  +    transform: translateY(0);
  +  }
  +}
  +
  +.folio-shift {
  +  animation: folio-feed 0.26s cubic-bezier(0.22, 1, 0.36, 1) both;
  +}
  +
  +/* The caret that trails the live value in the dossier preview. A real
  +   typewriter has no cursor, but the whole point of the preview is that
  +   the sheet on the left is being struck as you type on the right — the
  +   caret is what carries that across the gutter. */
  +.type-caret {
  +  display: inline-block;
  +  width: 0.45em;
  +  height: 1em;
  +  margin-left: 0.1em;
  +  vertical-align: -0.12em;
  +  background: var(--color-vermilion);
  +  animation: type-blink 1.05s steps(1, end) infinite;
  +}
  +
  +/* Platen rule: the baseline under a single-line answer thickens and
  +   colours as the carriage arrives. `background-size` animates from the
  +   centre out so the rule is drawn rather than swapped. */
  +.carriage-input {
  +  background-image: linear-gradient(
  +    to right,
  +    var(--color-vermilion),
  +    var(--color-mustard)
  +  );
  +  background-repeat: no-repeat;
  +  background-position: center bottom;
  +  background-size: 0% 2px;
  +  transition: background-size 0.22s cubic-bezier(0.22, 1, 0.36, 1);
  +}
  +.carriage-input:focus {
  +  background-size: 100% 2px;
  +}
  +
  +/* The field card on the preview that the writer is filling right now. */
  +.field-live {
  +  border-color: var(--color-vermilion);
  +  background: var(--color-paper);
  +  box-shadow: 0 0 0 1px
  +    color-mix(in srgb, var(--color-vermilion) 22%, transparent);
  +}
